                if (!collapsed) {
                    SidebarDemoLabel(group.title, modifier = Modifier.weight(1f))
                    SidebarDemoIcon(chevron, Modifier.rotate(if (!expanded && rtl) 180f else 0f))
                }
            }
            if (expanded) {
                SidebarMenuSub {
                    group.entries.forEach { entry ->
                        SidebarMenuSubItem {
                            SidebarMenuSubButton(entry, onClick = { onSelect(entry) }, isActive = selected == entry)
                        }
                    }
                }
            }
        }
    }

    @Composable
    private fun SidebarMenuScope.SidebarDemoProject(
        name: String,
        icon: ImageVector,
        copy: SidebarDemoCopy,
        selected: String?,
        onSelect: (String) -> Unit,
    ) {
        val mobile = sidebarState().isMobile
        DropdownMenu {
            SidebarMenuItem {
                SidebarMenuButton(onClick = { onSelect(name) }, label = name, isActive = selected == name) {
                    SidebarDemoIcon(icon)
                    SidebarDemoLabel(name)
                }
                DropdownMenuTrigger(label = copy.more) { modifier, onClick ->
                    SidebarMenuAction(
                        onClick = onClick,
                        label = copy.more,
                        modifier = modifier,
                        showOnHover = true,
                        expanded = open,
                    ) {
                        SidebarDemoIcon(Lucide.Ellipsis)
                    }
                }
            }
            DropdownMenuContent(
                side = if (mobile) PopupPlacement.Bottom else PopupPlacement.End,
                align = if (mobile) PopupAlign.End else PopupAlign.Start,
                style = Style { width(192.dp) },
            ) {
                DropdownMenuItem(copy.projectActions[0], onClick = { onSelect(name) })
                DropdownMenuItem(copy.projectActions[1], onClick = { onSelect(copy.projectActions[1]) })
                DropdownMenuSeparator()
                DropdownMenuItem(copy.projectActions[2], onClick = { onSelect(copy.projectActions[2]) })
            }
        }
    }

    @Composable
    private fun SidebarDemoAccount(
        actions: List<String>,
        avatar: Painter?,
        onSelect: (String) -> Unit,
    ) {
        val state = sidebarState()
        SidebarMenu {
            SidebarMenuItem {
                DropdownMenu {
                    DropdownMenuTrigger(label = "shadcn") { modifier, onClick ->
                        SidebarMenuButton(
                            modifier = modifier,
                            onClick = onClick,
                            label = "shadcn",
                            size = SidebarMenuButtonSize.Lg,
                            active = open,
                        ) {
                            SidebarDemoAvatar(avatar)
                            if (!state.iconCollapsed) {
                                SidebarDemoIdentity("shadcn", "m@example.com", Modifier.weight(1f))
                                SidebarDemoIcon(Lucide.ChevronsUpDown)
                            }
                        }
                    }
                    DropdownMenuContent(
                        side = if (state.isMobile) PopupPlacement.Bottom else PopupPlacement.End,
                        align = PopupAlign.End,
                        style = Style { width(224.dp) },
                    ) {
                        DropdownMenuLabel("m@example.com")
                        DropdownMenuSeparator()
                        actions.forEachIndexed { index, label ->
                            if (index == 1 || index == 4) DropdownMenuSeparator()
                            DropdownMenuItem(label, onClick = { onSelect(label) })
                        }
                    }
                }
            }
        }
    }

    @Composable
    private fun SidebarDemoAvatar(avatar: Painter?) {
        Avatar(
            style =
                Style {
                    shape(RoundedCornerShape(8.dp))
                    size(32.dp)
                },
        ) {
            if (avatar != null) AvatarImage(avatar)
            AvatarFallback("CN")
        }
    }

    @Composable
    private fun SidebarDemoIcon(
        glyph: ImageVector,
        modifier: Modifier = Modifier,
    ) {
        Icon(glyph, modifier.size(16.dp))
    }

    @Composable
    private fun SidebarDemoLabel(
        label: String,
        modifier: Modifier = Modifier,
        weight: FontWeight = FontWeight.Normal,
    ) {
        Text(
            modifier = modifier,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            textStyle = TextStyle(fontSize = 14.sp, lineHeight = 20.sp, fontWeight = weight),
        ) { label }
    }

