    @Composable
    internal fun SidebarRtlRecipe(
        arabicFont: FontFamily? = null,
        hebrewFont: FontFamily? = null,
        avatar: Painter? = null,
    ) {
        val languages = listOf("English", "Arabic (العربية)", "Hebrew (עברית)")
        var language by remember { mutableIntStateOf(1) }
        val theme = currentTheme
        val direction = if (language == 0) LayoutDirection.Ltr else LayoutDirection.Rtl
        val copy =
            when (language) {
                1 -> arabicSidebarCopy
                2 -> hebrewSidebarCopy
                else -> englishSidebarCopy
            }
        val font =
            when (language) {
                1 -> arabicFont
                2 -> hebrewFont
                else -> null
            }
        CompositionLocalProvider(LocalLayoutDirection provides direction) {
            Theme(
                preset = theme.activePreset,
                baseColor = theme.activeBaseColor,
                accent = theme.activeAccent,
                isDark = theme.isDark,
                baseRadius = theme.baseRadius,
                ring = theme.ring,
                unitSpacing = LocalUnitSpacing.current,
                minTouchTarget = theme.minTouchTarget,
                fontFamily = font ?: theme.fontFamily,
            ) {
                Box {
                    SidebarDemoShell(
                        copy = copy,
                        switchTeams = false,
                        variant = SidebarVariant.Floating,
                        modifier = Modifier.height(420.dp),
                        avatar = avatar,
                    )
                    Box(Modifier.align(Alignment.TopEnd).padding(16.dp)) {
                        Select(value = languages[language], onValueChange = { language = languages.indexOf(it) }) {
                            SelectTrigger(
                                Modifier.width(144.dp),
                                size = SelectSize.Sm,
                                accessibilityLabel = "Preview language",
                            )
                            SelectContent { languages.forEach { SelectItem(it) } }
                        }
                    }
                }
            }
        }
    }
    """.trimIndent()
